// ============================================================
// Helpers de búsqueda
// ============================================================
window.OLF_KNOW.findAromaByName = function(name) {
  if (!name) return null;
  const norm = String(name).toLowerCase().trim();
  return this.aromas.find(a =>
    a.nombre.toLowerCase().trim() === norm ||
    a.key === norm.replace(/[^a-z0-9]+/g,'_')
  ) || null;
};
window.OLF_KNOW.findDifusorByName = function(name) {
  if (!name) return null;
  const norm = String(name).toLowerCase().trim();
  return this.difusores.find(d =>
    d.modelo.toLowerCase().trim() === norm ||
    d.key === norm.replace(/[^a-z0-9]+/g,'_')
  ) || null;
};
